{
  "items": [
    {
      "title": "German General Social Survey (ALLBUS) – Cumulation 1980–2014",
      "url_or_doi": "https://search.gesis.org/research_data/ZA4584",
      "justification": "One of the most comprehensive datasets for studying political behaviour and attitudes across German federal states. Includes surveys from 1990, 1991, 1992, 1994, 1996, and 1998. Covers political participation, party identification, political interest, satisfaction with democracy, trust in government, and social attitudes. Includes respondents from the requested states. Federal-state identification may require access to the ALLBUS Extended version."
    },
    {
      "title": "German General Social Survey (ALLBUS) – Extended Datasets",
      "url_or_doi": "https://www.gesis.org/en/allbus/data-and-documentation",
      "justification": "Particularly suitable for state-level comparisons because the Extended datasets contain federal-state identifiers and additional regional classifications. Historical surveys from the 1990s allow comparisons of political attitudes and participation across Berlin, Baden-Württemberg, Bavaria, Bremen, Hesse, Hamburg, Lower Saxony, North Rhine-Westphalia, Rhineland-Palatinate, Saarland, and Schleswig-Holstein. Access to extended regional variables is subject to additional conditions."
    },
    {
      "title": "German General Social Survey (ALLBUScompact) – Cumulation 1980–2008",
      "url_or_doi": "https://search.gesis.org/research_data/ZA4573",
      "justification": "A harmonized collection of German population surveys covering the entire 1990s. Includes measures of political behaviour, political attitudes, social values, government evaluations, and political participation. Useful for examining long-term changes in political orientations, although the compact version has more limited regional information."
    },
    {
      "title": "German State Elections – Integrated Dataset 1962–2004",
      "url_or_doi": "https://doi.org/10.4232/1.12389",
      "justification": "Highly relevant integrated dataset combining German state election surveys, including elections conducted during the 1990s. Supports comparative analyses of electoral behaviour, party preferences, political orientations, and the influence of federal politics on state elections. Particularly useful for comparing political behaviour across the eleven requested federal states."
    },
    {
      "title": "Political Attitudes, Political Participation and Voting Behavior in Reunified Germany 1994",
      "url_or_doi": "https://doi.org/10.4232/1.11973",
      "justification": "National election study examining political attitudes, participation, and voting behaviour surrounding Germany's 1994 federal election. Includes evaluations of political parties and politicians, electoral preferences, and attitudes toward political developments after reunification. Relevant for comparing political orientations across German regions during the 1990s."
    },
    {
      "title": "Political Attitudes, Political Participation and Voting Behavior in Reunified Germany 1998",
      "url_or_doi": "https://doi.org/10.4232/1.11968",
      "justification": "Comprehensive federal election survey covering political preferences, voting decisions, political participation, party evaluations, and democratic attitudes in 1998. Especially valuable for studying the political changes associated with the 1998 federal election and comparing them with the 1994 survey."
    },
    {
      "title": "State Parliament Election in Baden-Württemberg 1992",
      "url_or_doi": "https://doi.org/10.4232/1.11245",
      "justification": "State-specific election survey examining political behaviour and electoral preferences surrounding Baden-Württemberg's 1992 state election. Suitable for analysing political party support, voting behaviour, and regional political attitudes during the early 1990s."
    },
    {
      "title": "State Parliament Election in Baden-Württemberg 1996",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2913",
      "justification": "Election study focused on Baden-Württemberg's 1996 state election. Provides material for investigating political preferences, electoral behaviour, and attitudes toward political parties. Can be compared with the 1992 study to identify changes during the decade."
    },
    {
      "title": "State Parliament Election in Bavaria 1990",
      "url_or_doi": "https://search.gesis.org/research_data/ZA1963",
      "justification": "Survey associated with Bavaria's 1990 state election. Relevant for examining party preferences, political attitudes, and electoral behaviour at the beginning of the decade."
    },
    {
      "title": "State Parliament Election in Bavaria 1990 – Post-Election Survey",
      "url_or_doi": "https://search.gesis.org/research_data/ZA1947",
      "justification": "Post-election study of the 1990 Bavarian state election. Particularly useful for analysing reported voting behaviour and retrospective evaluations of electoral choices and political parties."
    },
    {
      "title": "State Parliament Election in Bavaria 1994",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2506",
      "justification": "State election survey documenting electoral behaviour and political preferences during Bavaria's 1994 election. Useful for assessing changes in party support and regional political orientations."
    },
    {
      "title": "State Parliament Election in Bavaria 1998",
      "url_or_doi": "https://search.gesis.org/research_data/ZA3167",
      "justification": "Survey of Bavaria's 1998 state election, relevant for analysing party support, political attitudes, and electoral behaviour toward the end of the 1990s."
    },
    {
      "title": "Berlin House of Representatives Election 1995",
      "url_or_doi": "https://doi.org/10.4232/1.11268",
      "justification": "Election study focused on Berlin's 1995 House of Representatives election. Particularly relevant for investigating political preferences and electoral behaviour in reunified Berlin, including the political divisions between former East and West Berlin."
    },
    {
      "title": "Berlin House of Representatives Election 1999",
      "url_or_doi": "https://search.gesis.org/research_data/ZA3894",
      "justification": "Survey associated with Berlin's 1999 state election. Relevant for studying political attitudes, party preferences, and voting behaviour nearly a decade after German reunification. Enables comparisons with the 1995 Berlin election study."
    },
    {
      "title": "Bremen State Parliament Election 1991",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2119",
      "justification": "Election survey covering Bremen's 1991 Bürgerschaft election. Provides data relevant to electoral behaviour, political preferences, and party support during the early post-reunification period."
    },
    {
      "title": "Bremen State Parliament Election 1995",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2581",
      "justification": "Survey associated with Bremen's 1995 Bürgerschaft election. Useful for analysing changes in political preferences, party support, and voting behaviour during the middle of the 1990s."
    },
    {
      "title": "Bremen State Parliament Election 1999",
      "url_or_doi": "https://search.gesis.org/research_data/ZA3169",
      "justification": "Election survey documenting political behaviour surrounding Bremen's 1999 Bürgerschaft election. Can be compared with the 1991 and 1995 Bremen studies to examine changes in electoral preferences."
    },
    {
      "title": "Hamburg State Parliament Election 1991",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2118",
      "justification": "Survey of Hamburg's 1991 Bürgerschaft election. Relevant for analysing political behaviour, electoral preferences, and regional party competition in the early 1990s."
    },
    {
      "title": "Hamburg State Parliament Election 1993",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2398",
      "justification": "Election study of Hamburg's 1993 Bürgerschaft election. Useful for investigating voting patterns, political preferences, and changes in party support between elections."
    },
    {
      "title": "Hamburg State Parliament Election 1997",
      "url_or_doi": "https://search.gesis.org/research_data/ZA3030",
      "justification": "Survey covering Hamburg's 1997 state election. Provides data relevant to political attitudes, electoral behaviour, and party preferences. Enables comparisons with Hamburg's 1991 and 1993 election studies."
    },
    {
      "title": "Hesse State Parliament Election 1991 – Before the Gulf War",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2115",
      "justification": "Survey examining political orientations and electoral preferences in Hesse before the beginning of the 1991 Gulf War. Particularly valuable for studying how international political developments may have influenced regional electoral attitudes."
    },
    {
      "title": "Hesse State Parliament Election 1991 – After the Beginning of the Gulf War",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2116",
      "justification": "Survey examining political preferences and electoral attitudes in Hesse after the Gulf War began. Can be analysed alongside the corresponding pre-war survey to investigate changes in political orientations during a major international crisis."
    },
    {
      "title": "Hesse State Parliament Election 1995",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2582",
      "justification": "State election study focused on Hesse's 1995 election. Relevant for analysing voting behaviour, party preferences, and regional political attitudes in the middle of the decade."
    },
    {
      "title": "Hesse State Parliament Election 1999",
      "url_or_doi": "https://search.gesis.org/research_data/ZA3120",
      "justification": "Election study covering Hesse's 1999 state election. Useful for examining political preferences and electoral behaviour at the end of the decade, including comparisons with the 1991 and 1995 election studies."
    },
    {
      "title": "Lower Saxony State Parliament Election 1990",
      "url_or_doi": "https://search.gesis.org/research_data/ZA1934",
      "justification": "Survey covering Lower Saxony's 1990 state election. Relevant for analysing electoral preferences, political attitudes, and party support during the period of German reunification."
    },
    {
      "title": "Lower Saxony State Parliament Election 1994",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2509",
      "justification": "Election study examining political behaviour in Lower Saxony during the 1994 state election. Useful for studying regional party competition and changes in electoral preferences."
    },
    {
      "title": "Lower Saxony State Parliament Election 1998 – Pre-Election Survey",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2986",
      "justification": "Pre-election survey investigating political preferences before Lower Saxony's 1998 state election. Particularly useful for examining voting intentions and political attitudes before election day."
    },
    {
      "title": "Lower Saxony State Parliament Election 1998 – Election-Day Survey",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2987",
      "justification": "Election-day survey associated with Lower Saxony's 1998 state election. Useful for studying electoral decisions and comparing actual reported voting behaviour with pre-election intentions."
    },
    {
      "title": "Lower Saxony State Parliament Election 1998",
      "url_or_doi": "https://search.gesis.org/research_data/ZA3031",
      "justification": "Election study focused on Lower Saxony's 1998 state election. Provides additional material for examining political preferences, electoral behaviour, and regional party competition."
    },
    {
      "title": "North Rhine-Westphalia State Parliament Election 1990",
      "url_or_doi": "https://search.gesis.org/research_data/ZA1933",
      "justification": "State election survey examining political behaviour and electoral preferences in North Rhine-Westphalia in 1990. Relevant for investigating party competition and political orientations in Germany's most populous federal state."
    },
    {
      "title": "North Rhine-Westphalia State Parliament Election 1995",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2583",
      "justification": "Election study covering North Rhine-Westphalia's 1995 state election. Useful for examining political attitudes, electoral preferences, and changes in party support compared with the 1990 election."
    },
    {
      "title": "Rhineland-Palatinate State Parliament Election 1991",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2117",
      "justification": "Survey covering Rhineland-Palatinate's 1991 state election. Relevant for studying voting behaviour, political preferences, and the regional political landscape after German reunification."
    },
    {
      "title": "Rhineland-Palatinate State Parliament Election 1996",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2914",
      "justification": "State election survey examining political behaviour and electoral preferences in Rhineland-Palatinate in 1996. Can be compared with the 1991 study to investigate changes in party support."
    },
    {
      "title": "Saarland State Parliament Election 1990",
      "url_or_doi": "https://doi.org/10.4232/1.11234",
      "justification": "Election survey focused on Saarland's 1990 state election. Useful for examining regional voting behaviour, political party preferences, and political orientations."
    },
    {
      "title": "Saarland State Parliament Election 1994",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2510",
      "justification": "Survey covering Saarland's 1994 state election. Relevant for investigating electoral preferences, political attitudes, and changes in regional party competition during the 1990s."
    },
    {
      "title": "Saarland State Parliament Election 1999",
      "url_or_doi": "https://search.gesis.org/research_data/ZA3896",
      "justification": "Election study covering Saarland's 1999 state election. Useful for analysing political behaviour and party support at the end of the decade and comparing results with the 1990 and 1994 surveys."
    },
    {
      "title": "Schleswig-Holstein State Parliament Election 1992",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2302",
      "justification": "Election survey examining political behaviour and electoral preferences in Schleswig-Holstein during the 1992 state election. Relevant for understanding regional political attitudes and voting patterns."
    },
    {
      "title": "Schleswig-Holstein State Parliament Election 1996",
      "url_or_doi": "https://search.gesis.org/research_data/ZA2915",
      "justification": "Survey covering Schleswig-Holstein's 1996 state election. Useful for examining changes in voting behaviour, party preferences, and political orientations compared with the 1992 election."
    },
    {
      "title": "German Federal Election Studies 1949–2009 – GESIS Collection",
      "url_or_doi": "https://www.gesis.org/en/elections/german-federal-elections",
      "justification": "Official collection of German federal election studies, including the elections of 1990, 1994, and 1998. Provides access to studies of electoral behaviour, political attitudes, party identification, political participation, and government evaluations. Useful for comparing the requested states within a common national electoral context, subject to the regional identifiers available in individual datasets."
    },
    {
      "title": "German State Election Studies – GESIS Collection",
      "url_or_doi": "https://www.gesis.org/en/elections/german-state-elections",
      "justification": "Official GESIS catalogue containing state-specific political and electoral surveys for all eleven requested German federal states. Includes numerous studies conducted between 1990 and 1999, with separate datasets for individual elections and, in some cases, pre-election, election-day, and post-election surveys. Particularly valuable for identifying additional datasets and comparing political behaviour across states."
    }
  ]
}
